$defs=[];foreach(json_decode(file_get_contents(__DIR__.'/special-s1-fixture.json'),true,512,JSON_THROW_ON_ERROR)as$d)$defs[$d['ukid']]=$d;
function check(bool $v,string $why):void{if(!$v)throw new RuntimeException($why);}
function sc(int $id,string $ukid,string $owner,int $row,int $col):CardInstance{global $defs;$d=$defs[$ukid];return new CardInstance(instanceId:$id,ukid:$ukid,owner:$owner,zone:'field',row:$row,col:$col,hp:(int)$d['health'],hpMax:(int)$d['health'],move:(int)$d['move'],moveMax:(int)$d['move'],strikeWeak:(int)$d['strike_weak'],strikeMedium:(int)$d['strike_medium'],strikeStrong:(int)$d['strike_strong'],prop:json_decode($d['prop']??'{}',true)?:[]);}
function seed(string $ukid='s1_17',int $distance=2):GameState{$s=new GameState(91,101,202);$s->status='battle';$s->battle=['active'=>'host','turn'=>1,'strike'=>null];$s->addCard(sc(1,$ukid,'host',3,3));$s->addCard(sc(2,'s1_128','player',3+$distance,3));$s->addCard(sc(3,'s1_1','host',1,1));$s->addCard(sc(4,'s1_1','player',6,5));return$s;}
function cmd(GameState $s,string $actor,string $type,array $p=[]):mixed{$r=(new Engine(clock:fn()=>1800000000))->apply($s,$actor,new Command($type,$p));check($r->success,$type.': '.($r->error??''));return$r;}
function es(array $events,string $type):array{return array_values(array_filter($events,fn($e)=>$e['type']===$type));}
$results=[];$examples=[];
function pair(string $name,GameState $seed,Closure $run,Closure $verify,string $queue='4,6,2,5,3,1'):void{
 global $defs,$results,$examples;$out=[];
 foreach([false,true]as$observed){$_SESSION=['debug_roll'=>$queue];Dice::init();$s=GameState::fromArray($seed->toArray());$rec=$observed?new Recorder(91,1,[],[],true,fn($c)=>$defs[$c->ukid]['name']??null):null;$s->historyRecorder=$rec;$r=$run($s);$out[]=[$s->toArray(),serialize($r),Dice::remaining()];if($rec){$events=$rec->batch($s)->data()['events'];$verify($events,$s);if(in_array($name,['shot','shot hidden','native pending reroll:any'],true))$examples[$name]['structured']=array_map(fn($e)=>array_intersect_key($e,array_flip(['type','host','player'])),array_values(array_filter($events,fn($e)=>str_starts_with($e['type'],'attack.')||str_starts_with($e['type'],'dice.'))));foreach(['host','player']as$view){$lines=[];foreach($events as$e)if($e[$view]!==null&&($t=JournalText::format($e['type'],$e[$view],$view))!==null)$lines[]=$t;$examples[$name][$view]=$lines;}}}
 check($out[0]===$out[1],$name.' changed DTO, result or RNG');$results[]=$name;
}
function attackChecks(array $events,string $type):void{check(count(es($events,'attack.declared'))===1,'declaration once '.$type);$r=es($events,'attack.result');check(count($r)===1&&$r[0]['payload']['attack_type']===$type,'result once '.$type);check(count(es($events,'dice.rolled'))===1,'one real die '.$type);check(count(es($events,'dice.final'))===1,'one final die '.$type);$order=array_column($events,'type');check(array_search('attack.declared',$order)<array_search('dice.rolled',$order)&&array_search('dice.rolled',$order)<array_search('dice.final',$order)&&array_search('dice.final',$order)<array_search('attack.result',$order),'declaration / roll / final / result order '.$type);foreach($events as$e)if(str_starts_with($e['type'],'attack.')||str_starts_with($e['type'],'dice.'))check(!isset($e['payload']['defend']),'no artificial defender');}
foreach([['s1_17','shot',2],['s1_111','throw',2],['s1_5','discharge',2],['s1_2','uchr',2],['s1_153','magic',1],['s1_2','tap',1]]as[$ukid,$type,$distance]){
 $s=seed($ukid,$distance);$s->cards[1]->coins=$type==='tap'?1:0;
 pair($type,$s,fn($s)=>cmd($s,'host',$type==='uchr'?'uchr':'action',['card_id'=>1,'target_id'=>2,'action_key'=>$type]),fn($es)=>attackChecks($es,$type));
}
foreach(['death','armor','hidden','rejected','retry','bonus']as$case){$s=seed();if($case==='death')$s->cards[2]->hp=1;if($case==='armor')$s->cards[2]->armor=8;if($case==='hidden')$s->cards[1]->revealed=false;if($case==='bonus')$s->cards[1]->coins=2;
 if($case==='miss'){$s=seed('s1_4');}
 pair('shot '.$case,$s,function($s)use($case){if($case==='rejected')return(new Engine())->apply($s,'player',new Command('action',['card_id'=>1,'target_id'=>2,'action_key'=>'shot']));$r=cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'shot']);if($case==='retry'){ $before=$s->toArray();check(!(new Engine())->apply($s,'host',new Command('action',['card_id'=>1,'target_id'=>2,'action_key'=>'shot']))->success,'retry rejected');check($before===$s->toArray(),'retry inert');}return$r;},function($events)use($case){if($case==='rejected'){check(!es($events,'attack.declared')&&!es($events,'dice.rolled'),'rejection emits nothing');return;}attackChecks($events,'shot');if($case==='death')check(count(es($events,'combat.death'))===1,'death once');if($case==='armor')check(count(es($events,'health.armor'))===1,'armor once');if($case==='hidden'){ $e=es($events,'attack.result')[0];check($e['player']!==null&&!isset($e['player']['source_id'],$e['player']['value'],$e['player']['modifiers']),'hidden source fields');check(!str_contains(json_encode($e['player'],JSON_UNESCAPED_UNICODE),'Арбалетчик'),'hidden name');check(es($events,'dice.rolled')[0]['player']===null,'hidden die');}if($case==='bonus')check(es($events,'attack.result')[0]['payload']['modifiers']['coins']===4,'coin modifier');},$case==='miss'?'1,6,2,5,3':'4,6,2,5,3');
}
foreach(['plus:own','minus:own','reroll:any']as$choice){$s=seed();$s->cards[3]=sc(3,'s1_181','host',1,1);
 pair('native pending '.$choice,$s,function($s)use($choice){cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'shot']);cmd($s,'host','combat_instant_play',['card_id'=>3,'instant_key'=>'udacha']);for($i=0;$i<12;$i++){if(!empty($s->battle['pending_dice_choice'])){cmd($s,'host','choose_dice_choice',['choice'=>$choice]);continue;}$r=$s->battle['single_roll']??null;if(!$r||$r['stage']==='results')break;cmd($s,$r['instant_priority'],'combat_instant_pass');}
 $rec=$s->historyRecorder;$copy=GameState::fromArray($s->toArray());$copy->historyRecorder=$rec;foreach(get_object_vars($copy)as$k=>$v)$s->$k=$v;
 $token=InformationalWaitManager::token($s);cmd($s,'host','confirm_strike',['wait_id'=>$token]);cmd($s,'player','confirm_strike',['wait_id'=>InformationalWaitManager::token($s)]);for($i=0;$i<8&&!empty($s->battle['single_roll']['instant_priority']);$i++)cmd($s,$s->battle['single_roll']['instant_priority'],'combat_instant_pass');return$s->cards[2]->hp;
 },function($events)use($choice){attackChecks($events,'shot');$change=es($events,'dice.changed');check(count($change)===1&&$change[0]['payload']['operation']===explode(':',$choice)[0],'one applied change');check(count(es($events,'combat.wounds'))===1,'wounds once after continuation');});
}
$s=seed('s1_17');$s->cards[2]=sc(2,'s1_189','player',5,3);pair('temple full prevention',$s,fn($s)=>cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'shot']),function($es){check(count(es($es,'dice.rolled'))===2,'attack and defense actual dice');check(es($es,'attack.result')[0]['payload']['outcome']==='blocked','blocked result');check(!es($es,'combat.wounds'),'no fictitious wounds');});
$s=seed('s1_168');$s->cards[1]->flags[CardRoll::READY]=true;pair('prepared six no RNG',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));return CardRoll::roll($s,$s->cards[1],'ability');},function($es){check(!es($es,'dice.rolled')&&count(es($es,'dice.assigned'))===1,'assigned not rolled');});
$s=seed('s1_69');pair('throw miss',$s,fn($s)=>cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'throw']),function($es){attackChecks($es,'throw');check(es($es,'attack.result')[0]['payload']['outcome']==='miss','real weak zero miss');check(!es($es,'combat.wounds'),'zero no wounds');},'1,6,2,5,3');
$s=seed('s1_22');pair('bomb no die',$s,fn($s)=>cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'bomb']),function($es){check(!es($es,'dice.rolled')&&count(es($es,'attack.result'))===1,'fixed shot no die');});
$s=seed('s1_1',1);$s->cards[2]->closed=true;pair('ordinary strike regression',$s,fn($s)=>cmd($s,'host','strike',['card_id'=>1,'target_id'=>2]),function($es){check(count(es($es,'combat.started'))===1&&count(es($es,'combat.dice'))===1&&count(es($es,'combat.result'))===1,'ordinary events retained');check(!es($es,'attack.declared'),'ordinary not duplicated');});

function settle(GameState $s):void{for($i=0;$i<18;$i++){$strike=$s->battle['strike']??null;if(!$strike)return;if(($strike['state']??'')!=='results')throw new RuntimeException('Unexpected combat stage '.($strike['state']??''));$owner=in_array('host',$strike['confirmed']??[],true)?'player':'host';cmd($s,$owner,'confirm_strike',['wait_id'=>InformationalWaitManager::token($s)]);}throw new RuntimeException('ACK loop');}
$s=seed('s1_10');pair('triple discharge settlement',$s,function($s){cmd($s,'host','action',['card_id'=>1,'action_key'=>'triple_discharge']);foreach([2,4]as$id){cmd($s,'host','choose_multi_discharge',['target_ids'=>[$id]]);settle($s);}return$s->cards[2]->hp;},function($es){check(count(es($es,'attack.declared'))===2&&count(es($es,'attack.result'))===2,'series declares and settles each target once');check(count(es($es,'dice.rolled'))===2&&count(es($es,'combat.wounds'))===2,'series no extra dice/wounds');});
$s=seed('s1_160');pair('paired ranged native continuation',$s,function($s){cmd($s,'host','action',['card_id'=>1,'action_key'=>'paired_ranged']);foreach([2,4]as$id){$p=$s->battle['pending_paired_ranged'];cmd($s,'host','choose_paired_ranged',['operation_id'=>$p['id'],'stage'=>$p['stage'],'target_id'=>$id]);}settle($s);return$s->cards[2]->hp;},function($es){check(count(es($es,'attack.declared'))===2&&count(es($es,'attack.result'))===2,'paired each effect once');check(array_column(array_column(es($es,'attack.result'),'payload'),'attack_type')===['discharge','throw'],'paired real types/order');});
$s=seed('s1_57');$s->cards[1]->coins=1;pair('freeze actual single roll',$s,fn($s)=>cmd($s,'host','action',['card_id'=>1,'action_key'=>'ice_rain']),function($es){check(count(es($es,'dice.rolled'))===1&&!es($es,'combat.dice'),'single no fake defender');});
